#include <stddef.h>

static void insertion_sort(int values[], size_t count)
{
    for (size_t i = 1U; i < count; ++i) {
        int item = values[i];
        size_t j = i;
        while (j > 0U && values[j - 1U] > item) {
            values[j] = values[j - 1U];
            --j;
        }
        values[j] = item;
    }
}

int main(void)
{
    int values[] = {5, 2, 4, 2, 1};
    insertion_sort(values, sizeof values / sizeof values[0]);
    for (size_t i = 1U; i < sizeof values / sizeof values[0]; ++i) {
        if (values[i - 1U] > values[i]) return 1;
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int compare_ints(const void *left, const void *right)
{
    const int a = *(const int *)left;
    const int b = *(const int *)right;
    return (a > b) - (a < b);
}

int main(void)
{
    int values[] = {8, -3, 8, 0, 2};
    const size_t count = sizeof values / sizeof values[0];
    qsort(values, count, sizeof values[0], compare_ints);
    for (size_t i = 0U; i < count; ++i) {
        printf("%d\n", values[i]);
    }
    return 0;
}
